import{_ as a,o as e,c as r,a3 as i}from"./chunks/framework.DMtjdCb-.js";const h="/help/assets/library-overview.-2qEqHWT.png",f=JSON.parse('{"title":"开始使用","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/index.md","filePath":"zh-Hans/index.md"}'),n={name:"zh-Hans/index.md"};function l(o,t,d,s,c,m){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h1><p>AnimeMachine 把作品资料、追番订阅、已有收藏和播放器入口放在同一个页面。先完成一次“找到作品 → 下载一集 → 打开播放”，再按需要接入已有收藏和调整设置。</p><p><img src="'+h+'" alt="作品列表：查看封面、订阅与收藏状态" loading="lazy"></p><h2 id="选择部署方式" tabindex="-1">选择部署方式 <a class="header-anchor" href="#选择部署方式" aria-label="Permalink to &quot;选择部署方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现在准备在哪里运行？</th><th>从这里开始</th></tr></thead><tbody><tr><td>Windows 电脑，先试用或管理电脑上的动画</td><td><a href="./desktop.html#windows">电脑部署</a></td></tr><tr><td>飞牛、群晖等 NAS，或已安装 Docker 的服务器</td><td><a href="./docker.html">NAS 联合部署</a></td></tr><tr><td>macOS 或 Linux 电脑</td><td><a href="./desktop.html#macos-linux">电脑部署</a></td></tr><tr><td>已经打开 AnimeMachine 页面</td><td><a href="./first-use.html">首次打开</a></td></tr></tbody></table><p>电脑部署先启动 AnimeMachine，再按需要连接下载服务；NAS 默认组合会一起部署 AnimeMachine、Ani-RSS、qBittorrent 和资源采集器，并自动建立连接。</p><h2 id="按顺序完成第一次使用" tabindex="-1">按顺序完成第一次使用 <a class="header-anchor" href="#按顺序完成第一次使用" aria-label="Permalink to &quot;按顺序完成第一次使用&quot;">​</a></h2><ol><li>按设备完成部署，然后<a href="./first-use.html">登录并确认页面就绪</a>。</li><li><a href="./subscribe.html">订阅一部作品</a>，选择需要的字幕和版本。</li><li>下载完成后<a href="./playback.html">打开播放器</a>。</li><li>之后使用<a href="./continue-watching.html">一键继续观看</a>，或<a href="./collections.html">接入已有收藏</a>。</li></ol><p>本手册以《世界最强的魔女，就此开始》为主要示例。资源检索结果会随时间变化，按页面实际可用的集数和版本选择即可。</p><h2 id="如何对照阅读" tabindex="-1">如何对照阅读 <a class="header-anchor" href="#如何对照阅读" aria-label="Permalink to &quot;如何对照阅读&quot;">​</a></h2><p>每章对应一个完整任务，各步沿用页面上的按钮名称。点击截图可查看原图；中文、English、日本語可在右上角切换。</p><p>已经完成的章节可以跳过。遇到问题时，从<a href="./troubleshooting.html">常见问题</a>按现象查找；涉及某一步的说明也放在对应章节末尾。</p>',12)])])}const _=a(n,[["render",l]]);export{f as __pageData,_ as default};
